cat > /tmp/cmp.php <<'EOF'
<?php
$m = \Drupal::service('module_handler');
$active = array_keys($m->getModuleList());
$sync = \Drupal\Core\Config\FileStorage::class;
$storage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
$ext = $storage->read('core.extension');
$syncmods = array_keys($ext['module']);
$missing = array_diff($syncmods, $active);
$extra = array_diff($active, $syncmods);
echo "in sync not enabled: " . implode(', ', $missing) . PHP_EOL;
echo "enabled not in sync: " . implode(', ', $extra) . PHP_EOL;
echo "sync default theme: " . ($ext['theme'] ? implode(',', array_keys($ext['theme'])) : '') . PHP_EOL;
EOF
cd /workspace && cp /tmp/cmp.php /workspace/cmp_tmp.php && su ddevuser -c "ddev drush php:script cmp_tmp.php" 2>&1 | tail -8; rm -f /workspace/cmp_tmp.php
